#include <flint/nmod_mpoly.h>
#include <flint/ulong_extras.h>
#include <cassert>
#include <fstream>
#include <iostream>
#include <vector>
#include <string>
#include <chrono>
using namespace std;nmod_mpoly_ctx_t ctx;ulong prime;
struct Poly{nmod_mpoly_t p;Poly(){nmod_mpoly_init(p,ctx);}Poly(const Poly&a):Poly(){nmod_mpoly_set(p,a.p,ctx);}Poly(Poly&&a):Poly(){nmod_mpoly_swap(p,a.p,ctx);}Poly&operator=(Poly a){nmod_mpoly_swap(p,a.p,ctx);return *this;}~Poly(){nmod_mpoly_clear(p,ctx);}};
void read(istream&in,Poly&p){int n;in>>n;ulong ex[3],c;for(int k=0;k<n;k++){in>>c>>ex[0]>>ex[1]>>ex[2];nmod_mpoly_push_term_ui_ui(p.p,c,ex,ctx);}nmod_mpoly_sort_terms(p.p,ctx);nmod_mpoly_combine_like_terms(p.p,ctx);}
void write(ostream&out,const Poly&p){ulong ex[3];int n=nmod_mpoly_length(p.p,ctx);out<<n;for(int k=0;k<n;k++){nmod_mpoly_get_term_exp_ui(ex,p.p,k,ctx);out<<' '<<nmod_mpoly_get_term_coeff_ui(p.p,k,ctx);for(auto x:ex)out<<' '<<x;}out<<'\n';}
struct Factor{Poly p;long exp;};vector<Factor>facs;
void record(Poly p,long m){if(!m)return;assert(!nmod_mpoly_is_zero(p.p,ctx));if(nmod_mpoly_is_ui(p.p,ctx))return;nmod_mpoly_make_monic(p.p,p.p,ctx);for(size_t i=0;i<facs.size();i++){long n=facs[i].exp;if((m>0)==(n>0)){if(nmod_mpoly_equal(p.p,facs[i].p.p,ctx)){facs[i].exp+=m;return;}continue;}Poly g,p1,q1;assert(nmod_mpoly_gcd(g.p,p.p,facs[i].p.p,ctx));if(nmod_mpoly_is_ui(g.p,ctx))continue;assert(nmod_mpoly_divides(p1.p,p.p,g.p,ctx));assert(nmod_mpoly_divides(q1.p,facs[i].p.p,g.p,ctx));facs.erase(facs.begin()+i);record(q1,n);record(g,m+n);record(p1,m);return;}facs.push_back(Factor{p,m});}
void primitive(vector<vector<Poly>>&A){int n=A.size();Poly g,h,q;for(int pass=0;pass<2;pass++)for(int i=0;i<n;i++){ulong scalar=0;for(int j=0;j<n;j++){auto&v=pass?A[j][i]:A[i][j];if(!nmod_mpoly_is_zero(v.p,ctx)){scalar=nmod_mpoly_get_term_coeff_ui(v.p,0,ctx);break;}}assert(scalar);scalar=n_invmod(scalar,prime);for(int j=0;j<n;j++){auto&v=pass?A[j][i]:A[i][j];nmod_mpoly_scalar_mul_ui(v.p,v.p,scalar,ctx);}nmod_mpoly_zero(g.p,ctx);for(int j=0;j<n;j++){auto&v=pass?A[j][i]:A[i][j];assert(nmod_mpoly_gcd(h.p,g.p,v.p,ctx));g=h;if(nmod_mpoly_is_one(g.p,ctx))break;}assert(!nmod_mpoly_is_zero(g.p,ctx));if(nmod_mpoly_is_ui(g.p,ctx))continue;record(g,1);for(int j=0;j<n;j++){auto&v=pass?A[j][i]:A[i][j];assert(nmod_mpoly_divides(q.p,v.p,g.p,ctx));v=q;}}}
bool determinant(vector<vector<Poly>>A,int mi){auto start=chrono::steady_clock::now();int stage=0;while(A.size()>1){primitive(A);int n=A.size(),bi=-1,bj=-1;long cost=100000000;for(int i=0;i<n;i++)for(int j=0;j<n;j++){int l=nmod_mpoly_length(A[i][j].p,ctx);if(l&&l<cost){cost=l;bi=i;bj=j;}}assert(bi>=0);swap(A[0],A[bi]);for(auto&r:A)swap(r[0],r[bj]);record(A[0][0],-(n-2));vector<vector<Poly>>B(n-1,vector<Poly>(n-1));Poly x,y;for(int i=1;i<n;i++)for(int j=1;j<n;j++){nmod_mpoly_mul(x.p,A[0][0].p,A[i][j].p,ctx);nmod_mpoly_mul(y.p,A[i][0].p,A[0][j].p,ctx);nmod_mpoly_sub(B[i-1][j-1].p,x.p,y.p,ctx);}A=std::move(B);long terms=0;for(auto&r:A)for(auto&p:r)terms+=nmod_mpoly_length(p.p,ctx);double sec=chrono::duration<double>(chrono::steady_clock::now()-start).count();cerr<<"MINOR "<<mi<<" STAGE "<<stage++<<" SIZE "<<A.size()<<" TERMS "<<terms<<" SEC "<<sec<<'\n';if(sec>90||terms>20000000)return false;}record(A[0][0],1);for(auto&f:facs)assert(f.exp>=0);return true;}
int main(int argc,char**argv){assert(argc==3);ifstream in(argv[1]);ofstream out(argv[2]);assert(in&&out);int nr,nc,k;in>>nr>>nc>>k>>prime;nmod_mpoly_ctx_init(ctx,3,ORD_LEX,prime);{vector<vector<Poly>>A(nr,vector<Poly>(nc));for(auto&r:A)for(auto&p:r)read(in,p);int nminor;in>>nminor;vector<vector<Factor>>bags;for(int t=0;t<nminor;t++){vector<int>rows(k),cols(k);for(int&i:rows)in>>i;for(int&i:cols)in>>i;vector<vector<Poly>>B(k,vector<Poly>(k));for(int i=0;i<k;i++)for(int j=0;j<k;j++)B[i][j]=A[rows[i]][cols[j]];facs.clear();if(!determinant(B,t)){out<<"BOUNDED_STOP "<<t<<'\n';out.flush();return 3;}bags.push_back(facs);out<<"MINOR "<<t<<" FACTORS "<<facs.size()<<'\n';for(auto&f:facs)if(f.exp){out<<"EXP "<<f.exp<<'\n';write(out,f.p);}out.flush();assert(out.good());cerr<<"MINOR_PASS "<<t<<'\n';}facs.clear();}nmod_mpoly_ctx_clear(ctx);flint_cleanup();return 0;}
